import{_ as l,a0 as p,w as r,s as o,ao as u,I as e,x as s,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"Ubuntu 22.04 之 KVM 安装手札 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 22.04 之 KVM 安装手札 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 22.04 之 KVM 安装手札 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 22.04 之 KVM 安装手札 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220524 How to Install KVM on Ubuntu 22.04 -Jammy Jellyfish-","title":"Ubuntu 22.04 之 KVM 安装手札","tag":"202206","desc":""},"relativePath":"202206/20220524 How to Install KVM on Ubuntu 22.04 -Jammy Jellyfish-.md","filePath":"[post].md"}'),c={name:"202206/20220524 How to Install KVM on Ubuntu 22.04 -Jammy Jellyfish-.md"};function d(h,a,g,b,k,m){const t=p("Link");return r(),o("div",null,[a[15]||(a[15]=u(`<h1 id="ubuntu-22-04-之-kvm-安装手札" tabindex="-1">Ubuntu 22.04 之 KVM 安装手札 <a class="header-anchor" href="#ubuntu-22-04-之-kvm-安装手札" aria-label="Permalink to “Ubuntu 22.04 之 KVM 安装手札”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202206/01/171619m6dd7bjb8292bbb9.jpg" alt=""></p><p><strong>KVM</strong> 是 <ruby>基于内核的虚拟机<rt>Kernel-based Virtual Machine</rt></ruby> 的首字母缩写，这是一项集成在内核中的开源虚拟化技术。它是一种类型一（裸机）的<ruby>管理程序<rt>hypervisor</rt></ruby>，可以使内核能够作为一个<ruby>裸机管理程序<rt>bare-metal hypervisor</rt></ruby>。</p><p>在 KVM 之上可以运行 Windows 和 Liunx 虚拟机。每个虚拟机都独立于其它虚拟机和底层操作系统（宿主机系统），并拥有自己的 CPU、内存、网络接口、存储设备等计算资源。</p><p>本文将介绍在 Ubuntu 22.04 LTS（Jammy Jellyfish）中如何安装 KVM 。在文末，我们也将演示如何在安装 KVM 完成之后创建一台虚拟机。</p><h3 id="_1、更新-ubuntu-22-04" tabindex="-1">1、更新 Ubuntu 22.04 <a class="header-anchor" href="#_1、更新-ubuntu-22-04" aria-label="Permalink to “1、更新 Ubuntu 22.04”">​</a></h3><p>在一切开始前，打开终端并通过如下命令更新本地的软件包索引：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span></code></pre></div><h3 id="_2、检查虚拟化是否开启" tabindex="-1">2、检查虚拟化是否开启 <a class="header-anchor" href="#_2、检查虚拟化是否开启" aria-label="Permalink to “2、检查虚拟化是否开启”">​</a></h3><p>在进一步行动之前，首先需要检查你的 CPU 是否支持 KVM 虚拟化，确保你系统中有 VT-x（ vmx）英特尔处理器或 AMD-V（svm）处理器。</p><p>你可以通过运行如下命令，如果输出值大于 0，那么虚拟化被启用。否则，虚拟化被禁用，你需要启用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ egrep -c &#39;(vmx|svm)&#39; /proc/cpuinfo</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/SVM-VMX-Flags-Cpuinfo-linux.png" alt="SVM-VMX-Flags-Cpuinfo-linux"></p><p>根据上方命令输出，你可以推断出虚拟化功能已经启用，因为输出结果大于 0。如果虚拟化功能没有启用，请确保在系统的 BIOS 设置中启用虚拟化功能。</p><p>另外，你可以通过如下命令判断 KVM 虚拟化是否已经在运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kvm-ok</span></span></code></pre></div><p>运行该命令之前，请确保你已经安装了 <code>cpu-checker</code> 软件包，否则将提示未找到该命令的报错。</p><p>直接就在下面，你会得到如何解决这个问题的指示，那就是安装 <code>cpu-checker</code> 包。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/KVM-OK-Command-Not-Found-Ubuntu.png" alt="KVM-OK-Command-Not-Found-Ubuntu"></p><p>随后，通过如下命令安装 <code>cpu-checker</code> 软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install -y cpu-checker</span></span></code></pre></div><p>接着再运行 <code>kvm-ok</code> 命令，如果 KVM 已经启动，你将看到如下输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kvm-ok</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/KVM-OK-Command-Output.png" alt="KVM-OK-Command-Output"></p><h3 id="_3、在-ubuntu-22-04-上安装-kvm" tabindex="-1">3、在 Ubuntu 22.04 上安装 KVM <a class="header-anchor" href="#_3、在-ubuntu-22-04-上安装-kvm" aria-label="Permalink to “3、在 Ubuntu 22.04 上安装 KVM”">​</a></h3><p>随后，通过如下命令在 Ubuntu 22.04 中安装 KVM 以及其他相关虚拟化软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install -y qemu-kvm virt-manager libvirt-daemon-system virtinst libvirt-clients bridge-utils</span></span></code></pre></div><p>以下为你解释刚刚安装了哪些软件包：</p><ul><li><code>qemu-kvm</code> – 一个提供硬件仿真的开源仿真器和虚拟化包</li><li><code>virt-manager</code> – 一款通过 libvirt 守护进程，基于 QT 的图形界面的虚拟机管理工具</li><li><code>libvirt-daemon-system</code> – 为运行 libvirt 进程提供必要配置文件的工具</li><li><code>virtinst</code> – 一套为置备和修改虚拟机提供的命令行工具</li><li><code>libvirt-clients</code> – 一组客户端的库和API，用于从命令行管理和控制虚拟机和管理程序</li><li><code>bridge-utils</code> – 一套用于创建和管理桥接设备的工具</li></ul><h3 id="_4、启用虚拟化守护进程-libvirtd" tabindex="-1">4、启用虚拟化守护进程（libvirtd） <a class="header-anchor" href="#_4、启用虚拟化守护进程-libvirtd" aria-label="Permalink to “4、启用虚拟化守护进程（libvirtd）”">​</a></h3><p>在所有软件包安装完毕之后，通过如下命令启用并启动 libvirt 守护进程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable --now libvirtd</span></span>
<span class="line"><span>$ sudo systemctl start libvirtd</span></span></code></pre></div><p>你可以通过如下命令验证该虚拟化守护进程是否已经运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status libvirtd</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Libvirtd-Status-Ubuntu-Linux.png" alt="Libvirtd-Status-Ubuntu-Linux"></p><p>另外，请将当前登录用户加入 <code>kvm</code> 和 <code>libvirt</code> 用户组，以便能够创建和管理虚拟机。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -aG kvm $USER</span></span>
<span class="line"><span>$ sudo usermod -aG libvirt $USER</span></span></code></pre></div><p><code>$USER</code> 环境变量引用的即为当前登录的用户名。你需要重新登录才能使得配置生效。</p><h3 id="_5、创建网桥-br0" tabindex="-1">5、创建网桥（br0） <a class="header-anchor" href="#_5、创建网桥-br0" aria-label="Permalink to “5、创建网桥（br0）”">​</a></h3><p>如果你打算从本机（Ubuntu 22.04）之外访问 KVM 虚拟机，你必须将虚拟机的网卡映射至网桥。<code>virbr0</code> 网桥是 KVM 安装完成后自动创建的，仅做测试用途。</p><p>你可以通过如下内容在 <code>/etc/netplan</code> 目录下创建文件 <code>01-netcfg.yaml</code> 来新建网桥：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/netplan/01-netcfg.yaml</span></span>
<span class="line"><span>network:</span></span>
<span class="line"><span>  ethernets:</span></span>
<span class="line"><span>    enp0s3:</span></span>
<span class="line"><span>      dhcp4: false</span></span>
<span class="line"><span>      dhcp6: false</span></span>
<span class="line"><span>  # add configuration for bridge interface</span></span>
<span class="line"><span>  bridges:</span></span>
<span class="line"><span>    br0:</span></span>
<span class="line"><span>      interfaces: [enp0s3]</span></span>
<span class="line"><span>      dhcp4: false</span></span>
<span class="line"><span>      addresses: [192.168.1.162/24]</span></span>
<span class="line"><span>      macaddress: 08:00:27:4b:1d:45</span></span>
<span class="line"><span>      routes:</span></span>
<span class="line"><span>        - to: default</span></span>
<span class="line"><span>          via: 192.168.1.1</span></span>
<span class="line"><span>          metric: 100</span></span>
<span class="line"><span>      nameservers:</span></span>
<span class="line"><span>        addresses: [4.2.2.2]</span></span>
<span class="line"><span>      parameters:</span></span>
<span class="line"><span>        stp: false</span></span>
<span class="line"><span>      dhcp6: false</span></span>
<span class="line"><span>  version: 2</span></span></code></pre></div><p>保存并退出文件。</p><p>注：上述文件的配置是我环境中的，请根据你实际环境替换 IP 地址、网口名称以及 MAC 地址。</p><p>你可以通过运行 <code>netplan apply</code> 命令应用上述变更。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo netplan apply</span></span></code></pre></div><p>你可以通过如下 <code>ip</code> 命令，验证网桥 <code>br0</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip add show</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Network-Bridge-br0-ubuntu-linux.png" alt="Network-Bridge-br0-ubuntu-linux"></p><h3 id="_6、启动-kvm-虚拟机管理器" tabindex="-1">6、启动 KVM 虚拟机管理器 <a class="header-anchor" href="#_6、启动-kvm-虚拟机管理器" aria-label="Permalink to “6、启动 KVM 虚拟机管理器”">​</a></h3><p>当 KVM 安装完成后，你可以使用图形管理工具 <code>virt-manager</code> 创建虚拟机。你可以在 GNOME 搜索工具中搜索 <code>Virtual Machine Manager</code> 以启动。</p><p>点击搜索出来的图标即可：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Access-Virtual-Machine-Manager-Ubuntu-Linux.png" alt="Access-Virtual-Machine-Manager-Ubuntu-Linux"></p><p>虚拟机管理器界面如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Virtual-Machine-Manager-Interface-Ubuntu-Linux.png" alt="Virtual-Machine-Manager-Interface-Ubuntu-Linux"></p><p>你可以点击 “<ruby>文件<rt>File</rt></ruby>” 并选择 “<ruby>新建虚拟机<rt>New Virtual Machine</rt></ruby>”。你也可以点击下图所示的图标：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/New-Virtual-Machine-Icon-Virt-Manager.png" alt="New-Virtual-Machine-Icon-Virt-Manager"></p><p>在弹出的虚拟机安装向导将看到如下四个选项：</p><ul><li>本地安装介质（ISO 镜像或 CDROM）</li><li>网络安装（HTTP、HTTPS 和 FTP）</li><li>导入现有磁盘镜像</li><li>手动安装</li></ul><p>本文使用已下载的 ISO 镜像，你可以选择自己的 ISO 镜像，选择第一个选项，并点击 “<ruby>向前<rt>Forward</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Local-Install-Media-ISO-Virt-Manager.png" alt="Local-Install-Media-ISO-Virt-Manager"></p><p>下一步中，点击 “<ruby>浏览<rt>Browse</rt></ruby>” 选择 ISO 镜像位置。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Browse-ISO-File-Virt-Manager-Ubuntu-Linux.png" alt="Browse-ISO-File-Virt-Manager-Ubuntu-Linux"></p><p>在下一个窗口中点击 “<ruby>浏览本地<rt>Browse local</rt></ruby>” 选取本机中 ISO 镜像。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Browse-Local-ISO-Virt-Manager.png" alt="Browse-Local-ISO-Virt-Manager"></p><p>如下所示，我们选择了 Debian 11 ISO 镜像，随后点击 “<ruby>打开<rt>Open</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Choose-ISO-File-Virt-Manager.png" alt="Choose-ISO-File-Virt-Manager"></p><p>当 ISO 镜像选择后，点击 “<ruby>向前<rt>Forward</rt></ruby>” 进入下一步。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Forward-after-browsing-iso-file-virt-manager.png" alt="Forward-after-browsing-iso-file-virt-manager"></p><p>接着定义虚拟机所用内存大小以及 CPU 核心数，并点击 “<ruby>向前<rt>Forward</rt></ruby>” 。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Virtual-Machine-RAM-CPU-Virt-Manager.png" alt="Virtual-Machine-RAM-CPU-Virt-Manager"></p><p>下一步中，输入虚拟机磁盘空间，并点击 “<ruby>向前<rt>Forward</rt></ruby>” 继续。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Storage-for-Virtual-Machine-KVM-Virt-Manager.png" alt="Storage-for-Virtual-Machine-KVM-Virt-Manager"></p><p>如你需要将虚拟机网卡连接至网桥，点击 “<ruby>选择网络<rt>Network selection</rt></ruby>” 并选择 <code>br0</code> 网桥。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Network-Selection-KVM-Virtual-Machine-Virt-Manager.png" alt="Network-Selection-KVM-Virtual-Machine-Virt-Manager"></p><p>最后，点击 “<ruby>完成<rt>Finish</rt></ruby>” 按钮结束设置虚拟机。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Choose-Finish-to-OS-Installation-KVM-VM.png" alt="Choose-Finish-to-OS-Installation-KVM-VM"></p><p>稍等片刻，虚拟机的创建过程将开始。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Creating-Domain-Virtual-Machine-Virt-Manager.png" alt="Creating-Domain-Virtual-Machine-Virt-Manager"></p><p>当创建结束时，虚拟机将开机并进入系统安装界面。如下是 Debian 11 的安装选项。在这里你可以根据需要进行系统安装。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Virtual-Machine-Console-Virt-Manager.png" alt="Virtual-Machine-Console-Virt-Manager"></p><h3 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h3><p>至此，本文向你演示了如何在 Ubuntu 22.04 上 安装 KVM 虚拟化引擎。你的反馈对我们至关重要。</p><hr>`,84)),e("p",null,[a[1]||(a[1]=s("via: ",-1)),i(t,{href:"https://www.linuxtechi.com/how-to-install-kvm-on-ubuntu-22-04/"},{default:n(()=>[...a[0]||(a[0]=[s("https://www.linuxtechi.com/how-to-install-kvm-on-ubuntu-22-04/",-1)])]),_:1})]),e("p",null,[a[6]||(a[6]=s("作者：",-1)),i(t,{href:"https://www.linuxtechi.com/author/james/"},{default:n(()=>[...a[2]||(a[2]=[s("James Kiarie",-1)])]),_:1}),a[7]||(a[7]=s(" 选题：",-1)),i(t,{href:"https://github.com/lkxed"},{default:n(()=>[...a[3]||(a[3]=[s("lkxed",-1)])]),_:1}),a[8]||(a[8]=s(" 译者：",-1)),i(t,{href:"https://github.com/turbokernel"},{default:n(()=>[...a[4]||(a[4]=[s("turbokernel",-1)])]),_:1}),a[9]||(a[9]=s(" 校对：",-1)),i(t,{href:"https://github.com/wxy"},{default:n(()=>[...a[5]||(a[5]=[s("wxy",-1)])]),_:1})]),e("p",null,[a[12]||(a[12]=s("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[10]||(a[10]=[s("LCTT",-1)])]),_:1}),a[13]||(a[13]=s(" 原创编译，",-1)),i(t,{href:"https://linux.cn/"},{default:n(()=>[...a[11]||(a[11]=[s("Linux中国",-1)])]),_:1}),a[14]||(a[14]=s(" 荣誉推出",-1))])])}const V=l(c,[["render",d]]);export{f as __pageData,V as default};
